# Let's check what's available
import importlib
for mod_name in ['pysat', 'z3', 'pycosat', 'itertools', 'random', 'math']:
    try:
        importlib.import_module(mod_name)
        print(f"{mod_name} available")
    except:
        print(f"{mod_name} not available")

import z3

n = 21
s = z3.Solver()

# Edge variables (symmetric, only store i<j)
e = {}
for i in range(n):
    for j in range(i+1, n):
        e[(i,j)] = z3.Bool(f'e_{i}_{j}')

def edge(a, b):
    if a == b:
        return None
    if a < b:
        return e[(a,b)]
    else:
        return e[(b,a)]

# At least 21 edges
s.add(z3.PbGe([(e[(i,j)], 1) for i in range(n) for j in range(i+1, n)], 21))

# 3-coloring variables
c = [z3.Int(f'c_{i}') for i in range(n)]
for i in range(n):
    s.add(z3.And(c[i] >= 0, c[i] <= 2))

# Adjacent vertices must have different colors
for i in range(n):
    for j in range(i+1, n):
        s.add(z3.Implies(e[(i,j)], c[i] != c[j]))

# No triangles (3-cycles)
print("Adding triangle constraints...")
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            s.add(z3.Not(z3.And(e[(i,j)], e[(i,k)], e[(j,k)])))

# No 4-cycles
print("Adding 4-cycle constraints...")
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            for l in range(k+1, n):
                # 4-cycle i-j-k-l-i
                s.add(z3.Not(z3.And(e[(i,j)], e[(j,k)], e[(k,l)], e[(l,i)])))
                # 4-cycle i-j-l-k-i
                s.add(z3.Not(z3.And(e[(i,j)], e[(j,l)], e[(l,k)], e[(k,i)])))
                # 4-cycle i-k-j-l-i
                s.add(z3.Not(z3.And(e[(i,k)], e[(k,j)], e[(j,l)], e[(l,i)])))

print("Solving with 3-cycle and 4-cycle constraints...")
result = s.check()
print(f"Result: {result}")

if result == z3.sat:
    m = s.model()
    edges_list = []
    for i in range(n):
        for j in range(i+1, n):
            if z3.is_true(m[e[(i,j)]]):
                edges_list.append((i,j))
    print(f"Found graph with {len(edges_list)} edges")
    print(f"Edges: {edges_list}")
    colors_list = [m[c[i]].as_long() for i in range(n)]
    print(f"Colors: {colors_list}")

    # Check girth
    # Build adjacency
    adj = [[] for _ in range(n)]
    for (i,j) in edges_list:
        adj[i].append(j)
        adj[j].append(i)

    # BFS to find shortest cycle
    def shortest_cycle():
        min_cycle = n+1
        for start in range(n):
            dist = [-1]*n
            parent = [-1]*n
            dist[start] = 0
            q = [start]
            for u in q:
                for v in adj[u]:
                    if v == parent[u]:
                        continue
                    if dist[v] == -1:
                        dist[v] = dist[u] + 1
                        parent[v] = u
                        q.append(v)
                    elif v != parent[u]:
                        # Found a cycle
                        cycle_len = dist[u] + dist[v] + 1
                        if cycle_len < min_cycle:
                            min_cycle = cycle_len
        return min_cycle

    girth = shortest_cycle()
    print(f"Girth: {girth}")
else:
    print("UNSAT")

